// Cloudflare Worker 스크립트
// 스마트 세이프 트래블 가디언 (Safe Travel Guardian)
const htmlContent = '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>스마트 세이프 트래블 가디언 - 제주 & 전국 안심 여행</title>\n  <style>\n    /* 기본 리셋 및 다크 테마 */\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif;\n    }\n    :root {\n      --bg-main: #090d16;\n      --bg-card: #111827;\n      --bg-card-hover: #172033;\n      --border-color: #1f2937;\n      --text-main: #f1f5f9;\n      --text-muted: #94a3b8;\n      --emerald: #10b981;\n      --cyan: #06b6d4;\n      --rose: #f43f5e;\n      --amber: #f59e0b;\n      --indigo: #6366f1;\n      --purple: #a855f7;\n    }\n    body {\n      background-color: var(--bg-main);\n      color: var(--text-main);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      overflow-x: hidden;\n      user-select: none;\n    }\n\n    /* 상단 헤더 */\n    header {\n      width: 100%;\n      padding: 13px 28px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      border-bottom: 1px solid var(--border-color);\n      background-color: rgba(9, 13, 22, 0.95);\n      backdrop-filter: blur(12px);\n      position: sticky;\n      top: 0;\n      z-index: 100;\n    }\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      font-size: 13.5px;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      color: #cbd5e1;\n    }\n    .pulse-dot {\n      width: 10px;\n      height: 10px;\n      border-radius: 50%;\n      background-color: var(--emerald);\n      box-shadow: 0 0 12px var(--emerald);\n      animation: pulseAnim 2s infinite;\n    }\n    @keyframes pulseAnim {\n      0%, 100% { opacity: 1; transform: scale(1); }\n      50% { opacity: 0.4; transform: scale(0.85); }\n    }\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n    }\n    .live-status-pill {\n      font-size: 11px;\n      padding: 4px 10px;\n      border-radius: 9999px;\n      background: rgba(16, 185, 129, 0.15);\n      border: 1px solid rgba(16, 185, 129, 0.3);\n      color: #34d399;\n      font-weight: 600;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n    .progress-wrap {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .progress-bar-bg {\n      width: 160px;\n      height: 6px;\n      background-color: #1e293b;\n      border-radius: 9999px;\n      overflow: hidden;\n    }\n    .progress-bar-fill {\n      height: 100%;\n      width: 5.5%;\n      background: linear-gradient(90deg, var(--emerald), var(--cyan));\n      transition: width 0.3s ease;\n    }\n    .slide-counter {\n      font-size: 12px;\n      font-family: monospace;\n      color: #64748b;\n      font-weight: 600;\n    }\n\n    /* 슬라이드 캔버스 */\n    main {\n      flex: 1;\n      max-width: 1160px;\n      width: 100%;\n      margin: 0 auto;\n      padding: 24px 20px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      position: relative;\n      min-height: calc(100vh - 140px);\n    }\n    .slide {\n      display: none;\n      width: 100%;\n      flex-direction: column;\n      animation: fadeIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n    }\n    .slide.active {\n      display: flex;\n    }\n    @keyframes fadeIn {\n      from { opacity: 0; transform: translateY(12px); }\n      to { opacity: 1; transform: translateY(0); }\n    }\n\n    /* 뱃지 및 타이포그래피 */\n    .badge {\n      display: inline-flex;\n      align-items: center;\n      padding: 5px 13px;\n      border-radius: 9999px;\n      background: rgba(16, 185, 129, 0.12);\n      border: 1px solid rgba(16, 185, 129, 0.3);\n      color: #34d399;\n      font-size: 12.5px;\n      font-weight: 600;\n      margin-bottom: 14px;\n      align-self: flex-start;\n      gap: 6px;\n    }\n    .badge.red {\n      background: rgba(244, 63, 94, 0.12);\n      border-color: rgba(244, 63, 94, 0.3);\n      color: #fb7185;\n    }\n    .badge.amber {\n      background: rgba(245, 158, 11, 0.12);\n      border-color: rgba(245, 158, 11, 0.3);\n      color: #fbbf24;\n    }\n    .badge.cyan {\n      background: rgba(6, 182, 212, 0.12);\n      border-color: rgba(6, 182, 212, 0.3);\n      color: #38bdf8;\n    }\n    .badge.indigo {\n      background: rgba(99, 102, 241, 0.12);\n      border-color: rgba(99, 102, 241, 0.3);\n      color: #818cf8;\n    }\n    .badge.purple {\n      background: rgba(168, 85, 247, 0.12);\n      border-color: rgba(168, 85, 247, 0.3);\n      color: #c084fc;\n    }\n    .center .badge {\n      align-self: center;\n    }\n    h1 {\n      font-size: 40px;\n      font-weight: 800;\n      line-height: 1.25;\n      margin-bottom: 16px;\n      letter-spacing: -0.02em;\n    }\n    .gradient-text {\n      background: linear-gradient(90deg, #34d399, #22d3ee);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n    h2 {\n      font-size: 27px;\n      font-weight: 700;\n      margin-bottom: 14px;\n      line-height: 1.3;\n      letter-spacing: -0.01em;\n    }\n    p.desc {\n      font-size: 14px;\n      color: var(--text-muted);\n      line-height: 1.65;\n      margin-bottom: 20px;\n    }\n\n    /* 그리드 및 카드 디자인 */\n    .grid-3 {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 16px;\n      width: 100%;\n    }\n    .grid-2 {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      gap: 16px;\n      width: 100%;\n    }\n    .grid-4 {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 12px;\n      width: 100%;\n    }\n    .card {\n      background-color: var(--bg-card);\n      border: 1px solid var(--border-color);\n      border-radius: 14px;\n      padding: 18px 20px;\n      transition: transform 0.2s, border-color 0.2s;\n    }\n    .card:hover {\n      border-color: #334155;\n      transform: translateY(-2px);\n    }\n    .card h3 {\n      font-size: 15.5px;\n      font-weight: 700;\n      color: #fff;\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .card p {\n      font-size: 12.8px;\n      color: var(--text-muted);\n      line-height: 1.55;\n    }\n    .card-tag {\n      font-size: 10.5px;\n      font-weight: 700;\n      padding: 3px 8px;\n      border-radius: 4px;\n      background: rgba(16, 185, 129, 0.15);\n      color: #34d399;\n      display: inline-block;\n      margin-bottom: 8px;\n    }\n\n    /* 아키텍처 매트릭스 */\n    .arch-matrix {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 14px;\n      width: 100%;\n    }\n    .arch-col {\n      background: #0f172a;\n      border: 1px solid #1e293b;\n      border-radius: 12px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .arch-col-header {\n      font-size: 12px;\n      font-weight: 800;\n      border-bottom: 1px solid #1e293b;\n      padding-bottom: 6px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n    }\n    .arch-item {\n      background: #111827;\n      border: 1px solid #1f2937;\n      padding: 9px 10px;\n      border-radius: 8px;\n      font-size: 12px;\n      color: #cbd5e1;\n      line-height: 1.4;\n    }\n    .arch-item strong {\n      color: #fff;\n      display: block;\n      margin-bottom: 2px;\n    }\n\n    /* 프로세스 스텝 */\n    .step-container {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      width: 100%;\n    }\n    .step-box {\n      flex: 1;\n      background: var(--bg-card);\n      padding: 16px;\n      border-radius: 12px;\n      border: 1px solid var(--border-color);\n    }\n    .step-num {\n      font-size: 10.5px;\n      font-family: monospace;\n      color: #64748b;\n      margin-bottom: 5px;\n      display: block;\n    }\n    .arrow {\n      color: #475569;\n      font-size: 18px;\n      font-weight: 700;\n    }\n\n    /* UI 목업 */\n    .mockup {\n      background: #0f172a;\n      border: 1px solid rgba(244, 63, 94, 0.4);\n      padding: 20px;\n      border-radius: 16px;\n      box-shadow: 0 0 30px rgba(244, 63, 94, 0.08);\n    }\n    .mockup-row {\n      display: flex;\n      justify-content: space-between;\n      padding: 6.5px 0;\n      border-bottom: 1px solid #1e293b;\n      font-size: 12px;\n    }\n    .btn-emergency {\n      width: 100%;\n      padding: 12px;\n      margin-top: 14px;\n      background: #e11d48;\n      color: white;\n      border: none;\n      border-radius: 8px;\n      font-weight: 700;\n      font-size: 13px;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      transition: background 0.2s;\n    }\n    .btn-emergency:hover {\n      background: #be123c;\n    }\n\n    /* 11번 슬라이드: 인터랙티브 콘솔 */\n    .sim-panel {\n      background: #0d1322;\n      border: 1px solid #1e293b;\n      border-radius: 16px;\n      padding: 18px;\n      width: 100%;\n      display: grid;\n      grid-template-columns: 1fr 1fr 1fr;\n      gap: 16px;\n      box-shadow: 0 8px 32px rgba(0,0,0,0.3);\n    }\n    .sim-box {\n      background: #111827;\n      border: 1px solid #1f2937;\n      border-radius: 12px;\n      padding: 14px;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .sim-box-title {\n      font-size: 13px;\n      font-weight: 700;\n      color: #f1f5f9;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      border-bottom: 1px solid #1e293b;\n      padding-bottom: 6px;\n    }\n    .siren-btn {\n      padding: 12px;\n      border-radius: 10px;\n      font-size: 13px;\n      font-weight: 800;\n      border: none;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      transition: all 0.2s;\n    }\n    .siren-btn.off {\n      background: linear-gradient(135deg, #e11d48, #be123c);\n      color: #ffffff;\n      box-shadow: 0 4px 15px rgba(225, 29, 72, 0.4);\n    }\n    .siren-btn.on {\n      background: #334155;\n      color: #f87171;\n      border: 2px solid #ef4444;\n      animation: strobeBorder 0.6s infinite alternate;\n    }\n    @keyframes strobeBorder {\n      from { box-shadow: 0 0 10px #ef4444; border-color: #ef4444; }\n      to { box-shadow: 0 0 25px #3b82f6; border-color: #3b82f6; }\n    }\n    .screen-strobe {\n      position: fixed;\n      inset: 0;\n      pointer-events: none;\n      z-index: 999;\n      display: none;\n      opacity: 0.22;\n      animation: strobeFlash 0.3s infinite alternate;\n    }\n    @keyframes strobeFlash {\n      0% { background-color: #ff0033; }\n      100% { background-color: #0044ff; }\n    }\n    .sim-btn {\n      padding: 8px 10px;\n      background: #1e293b;\n      color: #e2e8f0;\n      border: 1px solid #334155;\n      border-radius: 6px;\n      font-size: 11.5px;\n      font-weight: 600;\n      cursor: pointer;\n      transition: all 0.2s;\n      text-align: left;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n    }\n    .sim-btn:hover {\n      background: #334155;\n      border-color: #64748b;\n    }\n    .sim-btn.danger:hover {\n      background: rgba(225, 29, 72, 0.2);\n      border-color: #f43f5e;\n      color: #fca5a5;\n    }\n    .sim-log {\n      background: #090d16;\n      border: 1px solid #1e293b;\n      border-radius: 8px;\n      padding: 8px 10px;\n      font-family: monospace;\n      font-size: 11px;\n      color: #a7f3d0;\n      max-height: 110px;\n      overflow-y: auto;\n      line-height: 1.55;\n    }\n    .quick-list {\n      display: flex;\n      flex-direction: column;\n      gap: 5px;\n      max-height: 130px;\n      overflow-y: auto;\n    }\n    .quick-item {\n      background: #0f172a;\n      border: 1px solid #1e293b;\n      padding: 7px 9px;\n      border-radius: 6px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      font-size: 11px;\n    }\n    .route-badge {\n      background: rgba(16, 185, 129, 0.2);\n      color: #34d399;\n      padding: 2px 6px;\n      border-radius: 4px;\n      font-size: 10px;\n      font-weight: 700;\n      cursor: pointer;\n    }\n    .route-badge:hover {\n      background: #10b981;\n      color: #000;\n    }\n\n    /* 테이블 스타일 (슬라이드 14, 17) */\n    .spec-table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 12px;\n      background: #0f172a;\n      border-radius: 10px;\n      overflow: hidden;\n      border: 1px solid #1e293b;\n    }\n    .spec-table th, .spec-table td {\n      padding: 9px 12px;\n      text-align: left;\n      border-bottom: 1px solid #1e293b;\n    }\n    .spec-table th {\n      background: #111827;\n      color: #94a3b8;\n      font-weight: 700;\n      font-size: 11.5px;\n    }\n    .spec-table tr:hover {\n      background: rgba(255,255,255,0.02);\n    }\n    .tag-diff-high {\n      color: #f43f5e;\n      background: rgba(244,63,94,0.15);\n      padding: 2px 6px;\n      border-radius: 4px;\n      font-weight: 700;\n      font-size: 10.5px;\n    }\n    .tag-diff-med {\n      color: #f59e0b;\n      background: rgba(245,158,11,0.15);\n      padding: 2px 6px;\n      border-radius: 4px;\n      font-weight: 700;\n      font-size: 10.5px;\n    }\n    .tag-diff-low {\n      color: #10b981;\n      background: rgba(16,185,129,0.15);\n      padding: 2px 6px;\n      border-radius: 4px;\n      font-weight: 700;\n      font-size: 10.5px;\n    }\n\n    /* 팝업 모달 */\n    .sim-modal {\n      position: fixed;\n      inset: 0;\n      background: rgba(0,0,0,0.75);\n      display: none;\n      align-items: center;\n      justify-content: center;\n      z-index: 1000;\n    }\n    .sim-modal-content {\n      background: #111827;\n      border: 1px solid #374151;\n      border-radius: 14px;\n      padding: 22px;\n      max-width: 440px;\n      width: 92%;\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n      box-shadow: 0 20px 40px rgba(0,0,0,0.6);\n      animation: modalPop 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    @keyframes modalPop {\n      from { transform: scale(0.92); opacity: 0; }\n      to { transform: scale(1); opacity: 1; }\n    }\n\n    /* 하단 컨트롤러 */\n    footer {\n      width: 100%;\n      padding: 12px 28px;\n      border-top: 1px solid var(--border-color);\n      background-color: rgba(9, 13, 22, 0.95);\n      backdrop-filter: blur(12px);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      position: sticky;\n      bottom: 0;\n      z-index: 100;\n    }\n    .key-tip {\n      font-size: 12px;\n      color: #64748b;\n    }\n    .btn-group {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    button.nav-btn {\n      padding: 8px 18px;\n      border-radius: 8px;\n      font-size: 13px;\n      font-weight: 700;\n      cursor: pointer;\n      border: none;\n      transition: all 0.2s;\n    }\n    button.nav-btn:active {\n      transform: scale(0.96);\n    }\n    .btn-prev {\n      background: #1e293b;\n      color: #cbd5e1;\n      border: 1px solid #334155;\n    }\n    .btn-prev:hover:not(:disabled) {\n      background: #334155;\n      color: #fff;\n    }\n    .btn-next {\n      background: var(--emerald);\n      color: #ffffff;\n      box-shadow: 0 2px 10px rgba(16, 185, 129, 0.3);\n    }\n    .btn-next:hover {\n      background: #059669;\n    }\n    .btn-full {\n      background: #1e293b;\n      color: #cbd5e1;\n      padding: 8px 12px;\n      border: 1px solid #334155;\n    }\n    .btn-full:hover {\n      background: #334155;\n    }\n    button:disabled {\n      opacity: 0.35;\n      cursor: not-allowed;\n    }\n\n    /* 반응형 */\n    @media (max-width: 960px) {\n      .grid-3, .arch-matrix, .sim-panel {\n        grid-template-columns: 1fr;\n      }\n      .grid-2 {\n        grid-template-columns: 1fr;\n      }\n      .step-container {\n        flex-direction: column;\n      }\n      .arrow {\n        transform: rotate(90deg);\n      }\n      h1 { font-size: 30px; }\n      h2 { font-size: 22px; }\n    }\n  </style>\n</head>\n<body>\n\n  <div id="screenStrobe" class="screen-strobe"></div>\n\n  <!-- 상단 네비게이션 -->\n  <header>\n    <div class="brand">\n      <div class="pulse-dot"></div>\n      <span>SAFE TRAVEL GUARDIAN</span>\n      <span class="live-status-pill">● 4대 영역 16대 안전망 & 관리자 시스템 가동 중</span>\n    </div>\n    <div class="header-actions">\n      <div class="progress-wrap">\n        <div class="progress-bar-bg">\n          <div id="progressBar" class="progress-bar-fill"></div>\n        </div>\n        <span id="slideCounter" class="slide-counter">01 / 18</span>\n      </div>\n    </div>\n  </header>\n\n  <!-- 슬라이드 본체 -->\n  <main>\n    <!-- 1번 슬라이드: 커버 -->\n    <section class="slide active center" style="text-align: center; max-width: 880px;">\n      <div class="badge">📍 4대 안전영역 & 16대 전방위 스마트 안심 생태계</div>\n      <h1>스마트 세이프 <br><span class="gradient-text">트래블 가디언</span></h1>\n      <p class="desc">\n        자연재해·조난부터 도심 범죄·신변 위협, 모빌리티 및 숙소 안전까지,<br>\n        <strong>상시 감시의 거부감</strong>은 지우고 <strong>단독 여행자의 위기 골든타임</strong>을 지키는 실시간 통합 수호자\n      </p>\n      <div class="grid-3" style="margin-top: 10px;">\n        <div class="card">\n          <p style="color:#64748b; font-size:11px;">사전 위험 차단</p>\n          <h3>기상·치안 레이더 & AI 동행</h3>\n          <p style="font-size:12px; margin-top:4px;">일출몰·만조·우범지대·성범죄자 알림 & 가짜 통화</p>\n        </div>\n        <div class="card">\n          <p style="color:#64748b; font-size:11px;">은밀 & 통신음영 대응</p>\n          <h3>스텔스 SOS & 오프라인 BLE</h3>\n          <p style="font-size:12px; margin-top:4px;">주머니 속 무음 신고 및 기지국 두절 시 P2P 메시</p>\n        </div>\n        <div class="card">\n          <p style="color:#64748b; font-size:11px;">초동 대피 & 119 직결</p>\n          <h3>안심포인트 & 119 리포트</h3>\n          <p style="font-size:12px; margin-top:4px;">학교·편의점·병원 최단 대피 & 소방청 원클릭 전송</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 2번 슬라이드: 문제점 -->\n    <section class="slide">\n      <span class="badge red">PROBLEM & CHALLENGE</span>\n      <h2>나홀로 여행객이 직면하는 3대 현실적 복합 위기</h2>\n      <p class="desc">1인 여행객이 급증하고 있으나, 기존 단순 위치공유 서비스는 사각지대를 해결하지 못합니다.</p>\n      <div class="grid-3">\n        <div class="card">\n          <div class="card-tag" style="color:#f43f5e; background:rgba(244,63,94,0.15);">01</div>\n          <h3>프라이버시 반발 & 오경보 피로</h3>\n          <p>24시간 감시당하는 느낌으로 앱을 꺼버리거나, 단순 카페 휴식(10분 정지)마다 보호자에게 알림이 울려 양치기 소년이 됩니다.</p>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="color:#f59e0b; background:rgba(245,158,11,0.15);">02</div>\n          <h3>자연 환경 급변 & 통신 음영</h3>\n          <p>산간 지역의 급격한 일몰, 해안 만조(밀물), 곶자왈 숲속의 LTE 통신 두절, 배터리 급방전 등 예측 불가능한 지리적 조난 변수가 존재합니다.</p>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="color:#38bdf8; background:rgba(56,189,248,0.15);">03</div>\n          <h3>외진 골목 치안 & 신변 위협 무방비</h3>\n          <p>우범지대나 성범죄자 주거지 통과 시 사전 경각심이 없고, 위기 시 폰을 꺼내 신고하기 어려운 치한 대치 상황에 대피처를 찾지 못합니다.</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 3번 슬라이드: 4대 영역 16대 통합 아키텍처 매트릭스 -->\n    <section class="slide">\n      <span class="badge cyan">FULL ARCHITECTURE MATRIX</span>\n      <h2>차세대 가디언 4대 영역 & 16대 스마트 안전 체계</h2>\n      <p class="desc">사전 예방부터 이동 중 실시간 감시, 초동 대응, 모빌리티 및 커뮤니티 구난까지 빈틈없는 보호망을 제공합니다.</p>\n      <div class="arch-matrix">\n        <div class="arch-col">\n          <div class="arch-col-header" style="color:#34d399;">\n            <span>1. 사전 예방 레이더</span>\n            <span>PREVENT</span>\n          </div>\n          <div class="arch-item"><strong>기관데이터 연동</strong>기상청 날씨·특보, 천문연 일출몰, 해양조사원 만조</div>\n          <div class="arch-item"><strong>범죄위험 지오펜스</strong>경찰청 치안통계 기반 우범지대·취약골목 햅틱 경고</div>\n          <div class="arch-item"><strong>성범죄자 알림e 연계</strong>반경 200m 접근 시 지능형 사전 주의 가이드</div>\n          <div class="arch-item"><strong>숙소 불법촬영 점검</strong>IR 적외선 렌즈 탐지 & Wi-Fi 비인가 IP 스캐닝</div>\n        </div>\n        <div class="arch-col">\n          <div class="arch-col-header" style="color:#38bdf8;">\n            <span>2. 지능형 모니터링</span>\n            <span>MONITOR</span>\n          </div>\n          <div class="arch-item"><strong>단독 궤적추적</strong>올레길·등산로 Breadcrumb 기록 & 코스 이탈 감지</div>\n          <div class="arch-item"><strong>2단계 데드맨 스위치</strong>10분 정체 본인확인 ➔ 3분 무응답 시에만 비상 전파</div>\n          <div class="arch-item"><strong>라스트 핑 & 블랙박스</strong>음영 직전 좌표 백업 & 방전 직전 저전력 BLE 비콘</div>\n          <div class="arch-item"><strong>야생동물 출몰 경보</strong>제주 들개·멧돼지 DB & 20kHz 퇴치 주파수</div>\n        </div>\n        <div class="arch-col">\n          <div class="arch-col-header" style="color:#fb7185;">\n            <span>3. 위기 대응 & 탈출</span>\n            <span>RESPONSE</span>\n          </div>\n          <div class="arch-item"><strong>주머니 속 스텔스 SOS</strong>화면 꺼진 채 전원 5회 클릭 ➔ 30초 녹음 & 은밀 신고</div>\n          <div class="arch-item"><strong>AI 가짜 통화 동행</strong>밤길 가상 동행 대화 연출로 범죄 시도 사전 억제</div>\n          <div class="arch-item"><strong>최대 볼륨 비상 사이렌</strong>진동/무음 강제 해제, 120dB 음향 & 스트로브 플래시</div>\n          <div class="arch-item"><strong>안심포인트 & 병원 대피</strong>학교·편의점·주유소·지구대 & 응급실 최단 대피로</div>\n        </div>\n        <div class="arch-col">\n          <div class="arch-col-header" style="color:#c084fc;">\n            <span>4. 모빌리티 & 연대</span>\n            <span>ECOSYSTEM</span>\n          </div>\n          <div class="arch-item"><strong>피어(이용자) SOS</strong>반경 1km 내 동료 여행자 & 로컬 지킴이 긴급 협조</div>\n          <div class="arch-item"><strong>모빌리티 세이프티</strong>택시 비정상 이탈 감지 & 렌터카 전복 충격 e-Call</div>\n          <div class="arch-item"><strong>올레길 안심 동행 매칭</strong>PASS 신원 인증 기반 1인 여행자 세이프 버디</div>\n          <div class="arch-item"><strong>119 직결 & 다국어 TTS</strong>국가지점번호 리포트 & 외국인 음성 자동 번역</div>\n        </div>\n      </div>\n    </section>\n\n    <!-- 4번 슬라이드: 공공데이터 & 위험 지오펜싱 -->\n    <section class="slide">\n      <span class="badge amber">DEEP DIVE 01 : RISK RADAR</span>\n      <h2>공공데이터 기반 동적 환경 & 범죄·치안 위험 지오펜스</h2>\n      <p class="desc">정부 공공데이터 포털 및 경찰청/여가부 API를 실시간 융합하여 여행자 주변의 위험을 사전 차단합니다.</p>\n      <div class="grid-3">\n        <div class="card">\n          <div style="font-size:26px; margin-bottom:12px;">🌅</div>\n          <h3>기상 & 일출·일몰·만조 연동</h3>\n          <p>\n            <strong>기상청 & 한국천문연구원:</strong> 당일 일몰 30분 전 산악 하산 권고 알림 발송.<br>\n            <strong>국립해양조사원:</strong> 갯바위 낚시나 해변 도보 시 만조 40분 전 긴급 대피 경보.\n          </p>\n        </div>\n        <div class="card">\n          <div style="font-size:26px; margin-bottom:12px;">🚨</div>\n          <h3>범죄다수 발생지역 지오펜싱</h3>\n          <p>\n            지자체 안전지도 및 경찰청 치안통계를 결합하여, 야간 조도 미비 골목이나 우범 지역 진입 시<br>\n            스마트폰에 <strong>주의 햅틱 및 안전 우회로 제안</strong>을 실시간 발송합니다.\n          </p>\n        </div>\n        <div class="card">\n          <div style="font-size:26px; margin-bottom:12px;">🛡️</div>\n          <h3>성범죄자 주거지 접근 알림</h3>\n          <p>\n            여성가족부 <strong>성범죄자 알림e 데이터</strong> 기반으로 체류지 및 도보 반경 내 고위험자 주거 밀집구역 통과 시<br>\n            프라이버시를 침해하지 않는 반경 가이드로 사전 경각심을 고취합니다.\n          </p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 5번 슬라이드: 단독여행자 실시간 추적 & 2단계 체크인 -->\n    <section class="slide">\n      <span class="badge">DEEP DIVE 02 : SMART TRACKING</span>\n      <h2>단독여행자 실시간 궤적추적 & 2단계 체크인 (Dead Man\'s Switch)</h2>\n      <p class="desc">여행자의 자유를 방해하지 않으면서, 의식 불명이나 실종 위험 순간에만 정확하게 개입합니다.</p>\n      <div class="step-container" style="margin-bottom: 20px;">\n        <div class="step-box">\n          <span class="step-num">STEP 01</span>\n          <h3 style="font-size:15px; margin-bottom:6px; color:#fff;">안전 궤적 & 이탈 감지</h3>\n          <p style="font-size:12px; color:#94a3b8;">올레길·등산로 브레드크럼(Breadcrumb) 실시간 기록. 코스 이탈 또는 위험지역 10분 정체 감지</p>\n        </div>\n        <div class="arrow">➔</div>\n        <div class="step-box" style="border-color: rgba(245,158,11,0.5);">\n          <span class="step-num" style="color:#f59e0b;">STEP 02 (본인 확인)</span>\n          <h3 style="font-size:15px; margin-bottom:6px; color:#fde68a;">진동 & "안전하신가요?"</h3>\n          <p style="font-size:12px; color:#94a3b8;">화면 탭, 폰 흔들림, "괜찮아요" 음성 시 즉시 정상 해제 (오경보 90% 이상 사전 차단)</p>\n        </div>\n        <div class="arrow">➔</div>\n        <div class="step-box" style="border-color: rgba(244,63,94,0.5);">\n          <span class="step-num" style="color:#f43f5e;">STEP 03 (비상 전파)</span>\n          <h3 style="font-size:15px; margin-bottom:6px; color:#fca5a5;">보호자 & 119 카드 발송</h3>\n          <p style="font-size:12px; color:#94a3b8;">3분 무응답 시 보호자 앱에 "현재 좌표 + 국가지점번호 + 통화 유도 카드" 자동 전송</p>\n        </div>\n      </div>\n      <div class="card" style="background:#0f172a; border-color:#334155;">\n        <div style="display:flex; align-items:center; gap:12px;">\n          <span style="font-size:22px;">📡</span>\n          <div>\n            <h4 style="font-size:14px; color:#38bdf8; margin-bottom:3px;">곶자왈·산악 \'라스트 핑(Last Ping)\' 백업</h4>\n            <p style="font-size:12px; color:#94a3b8;">수풀이나 산간 음영으로 기지국 신호가 끊기기 직전의 마지막 정상 GPS 좌표와 배터리 잔량을 중앙 서버에 박제하여 수색 범위를 90% 이상 단축합니다.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- 6번 슬라이드: 신변 위협 & 범죄 차단 특화 -->\n    <section class="slide">\n      <span class="badge red">DEEP DIVE 03 : STEALTH & AI DEFENSE</span>\n      <h2>주머니 속 스텔스 무음 SOS, AI 가상 동행 & 숙소 안전 점검</h2>\n      <p class="desc">가해자에게 들키지 않고 은밀하게 신고하거나, 으슥한 길에서 심리적 안전과 방어막을 형성합니다.</p>\n      <div class="grid-3">\n        <div class="card" style="border-color:rgba(244,63,94,0.4);">\n          <div style="font-size:26px; margin-bottom:10px;">🕵️</div>\n          <h3 style="color:#fb7185;">주머니 속 스텔스 무음 SOS</h3>\n          <p>\n            화면을 켜지 않고 주머니 속에서 <strong>전원 버튼 5회 연속 클릭</strong> 시, 화면은 꺼진 상태를 유지하며 <strong>주변 현장 오디오 30초 자동 녹음 + 실시간 정밀 좌표</strong>를 보호자 및 112 상황실에 은밀히 자동 전송합니다.\n          </p>\n        </div>\n        <div class="card" style="border-color:rgba(99,102,241,0.4);">\n          <div style="font-size:26px; margin-bottom:10px;">📞</div>\n          <h3 style="color:#a5b4fc;">AI 가짜 통화 & 가상 동행</h3>\n          <p>\n            어두운 골목길을 지날 때 치한 접근을 차단하기 위해, "응 나 지금 숙소 다 왔어~" 등 자연스러운 <strong>AI 음성 대화형 가짜 통화 화면</strong>을 원터치 실행하여 통화 중인 상황을 연출하고 위치를 실시간 중계합니다.\n          </p>\n        </div>\n        <div class="card" style="border-color:rgba(168,85,247,0.4);">\n          <div style="font-size:26px; margin-bottom:10px;">🔍</div>\n          <h3 style="color:#d8b4fe;">숙소 안심 & 몰카 탐지 모드</h3>\n          <p>\n            게스트하우스·모텔·에어비앤비 체크인 시, 스마트폰 카메라 적외선(IR) 센서를 활용한 <strong>불법촬영 렌즈 탐지 가이드</strong> 및 숙소 공유 와이파이 내 비인가 IP 카메라 실시간 스캐닝 기능을 제공합니다.\n          </p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 7번 슬라이드: 극한 자연 & 모빌리티 세이프티 -->\n    <section class="slide">\n      <span class="badge purple">DEEP DIVE 04 : NATURE & MOBILITY</span>\n      <h2>오프라인 BLE 메시 릴레이, 블랙박스 비콘 & 모빌리티 e-Call</h2>\n      <p class="desc">통신이 터지지 않는 극한 산악부터 렌터카 야간 주행까지 전천후 이동 안전을 보장합니다.</p>\n      <div class="grid-2">\n        <div class="card">\n          <div class="card-tag" style="background:rgba(168,85,247,0.15); color:#c084fc;">통신 음영 & 자연 조난</div>\n          <h3>기지국 두절 시 P2P 메시 & 야생동물 퇴치</h3>\n          <p style="margin-bottom:10px;">인터넷이 끊겨도 작동하는 하드웨어 저전력 기술과 지역 생태계 데이터를 결합했습니다.</p>\n          <ul style="list-style:none; font-size:12.5px; color:#cbd5e1; display:flex; flex-direction:column; gap:7px;">\n            <li>📶 <strong>오프라인 BLE 메시 릴레이:</strong> 통신 음영 시 반경 100m 내 타 등산객 단말과 블루투스 P2P 통신으로 조난 신호 연쇄 전달</li>\n            <li>🔋 <strong>배터리 3% 라스트 블랙박스 비콘:</strong> 방전 직전 초절전 모드 진입, 최소 전력 BLE 핑 방출로 수색 드론/수색견 탐지 유도</li>\n            <li>🐗 <strong>야생동물 출몰 경보 & 기피 주파수:</strong> 제주 중산간 들개 무리, 멧돼지 출몰지 경고 및 20kHz~25kHz 동물 기피 고주파 방출</li>\n          </ul>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="background:rgba(6,182,212,0.15); color:#38bdf8;">모빌리티 안심망</div>\n          <h3>택시 경로이탈 감지 & 렌터카 사고 e-Call</h3>\n          <p style="margin-bottom:10px;">나홀로 여행자가 이용하는 대중교통과 렌터카의 이동 중 위기 상황을 감지합니다.</p>\n          <ul style="list-style:none; font-size:12.5px; color:#cbd5e1; display:flex; flex-direction:column; gap:7px;">\n            <li>🚕 <strong>택시 비정상 경로 이탈 감지:</strong> 목적지 권장 경로에서 20% 이상 벗어나거나 외딴길 진입 시 자동 진동 및 경로 보호자 공유</li>\n            <li>🚗 <strong>렌터카 충격/전복 감지 e-Call:</strong> 스마트폰 자이로 센서로 급격한 충돌·전복 감지 시 30초 내 미해제 시 119/렌터카사 자동 접수</li>\n            <li>🤝 <strong>올레길 안심 동행 매칭:</strong> 본인 확인(PASS) 인증 1인 여행자 간 안전 버디 매칭으로 외진 숲길 동행 걷기 지원</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <!-- 8번 슬라이드: 안심포인트 & 인근 병원 최단 대피망 -->\n    <section class="slide">\n      <span class="badge indigo">DEEP DIVE 05 : SAFE HAVEN</span>\n      <h2>여행자 안심포인트 & 응급의료기관 최단경로 대피망</h2>\n      <p class="desc">위기나 신변 위협을 감지했을 때, 당황하지 않고 가장 안전한 피난처로 즉시 도보 이동할 수 있도록 안내합니다.</p>\n      <div class="grid-2">\n        <div class="card">\n          <div class="card-tag" style="background:rgba(99,102,241,0.15); color:#818cf8;">안심포인트 4대 거점</div>\n          <h3>비상 시 즉시 몸을 숨기는 안전 대피처</h3>\n          <p style="margin-bottom:12px;">반경 500m 이내 최단거리 거점을 자동 선별하여 원터치 도보 내비게이션을 지원합니다.</p>\n          <ul style="list-style:none; font-size:12.5px; color:#cbd5e1; display:flex; flex-direction:column; gap:8px;">\n            <li>🏫 <strong>학교지킴이집:</strong> 전담 보안관 상주 및 아동/여성 긴급 피난 공간</li>\n            <li>🏪 <strong>24시 안심편의점:</strong> 112 직결 비상벨 및 카운터 내 대피 시설 구비</li>\n            <li>⛽ <strong>안심 주유소:</strong> 24시간 조명 점등 및 상주 인력 비상 지원망</li>\n            <li>👮 <strong>관공서 & 지구대/파출소:</strong> 최우선 안전 피난 및 경찰 현장 대응</li>\n          </ul>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="background:rgba(244,63,94,0.15); color:#fb7185;">의료 응급망</div>\n          <h3>인근 병원, 권역 응급센터 & AED 안내</h3>\n          <p style="margin-bottom:12px;">야간이나 휴일에도 진료 중인 가장 가까운 응급실과 의료기관을 직통 연결합니다.</p>\n          <ul style="list-style:none; font-size:12.5px; color:#cbd5e1; display:flex; flex-direction:column; gap:8px;">\n            <li>🏥 <strong>야간·휴일 진료 병의원:</strong> 실시간 진료 가능 여부 및 도보/차량 소요시간 표시</li>\n            <li>🚑 <strong>권역 응급의료센터:</strong> 중증 외상 및 심정지 대비 응급실 직통 다이얼</li>\n            <li>⚡ <strong>자동심장충격기(AED) 위치:</strong> 반경 200m 내 공공 AED 비치함 핀포인트 안내</li>\n            <li>🩺 <strong>의료정보 사전공유:</strong> 지병, 알레르기, 혈액형 정보 응급대원 자동 전송</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <!-- 9번 슬라이드: 위기 탈출 3대 대응책 & 피어 SOS -->\n    <section class="slide">\n      <span class="badge red">DEEP DIVE 06 : CRISIS RESPONSE</span>\n      <h2>위기 탈출 3대 대응책: 강제 사이렌, 상황별 연락, 피어 SOS</h2>\n      <p class="desc">가장 위험한 현장에서 여행자의 생명을 구하는 능동적이고 즉각적인 구난 인터랙션입니다.</p>\n      <div class="grid-3">\n        <div class="card" style="border-color:rgba(244,63,94,0.4);">\n          <div style="font-size:26px; margin-bottom:10px;">📢</div>\n          <h3 style="color:#fb7185;">최대 볼륨 비상 사이렌</h3>\n          <p>\n            휴대폰이 <strong>매너모드나 진동 상태</strong>여도 강제로 미디어 볼륨 100%로 120dB급 소방/경찰 사이렌 사운드를 방출하고, 카메라 플래시와 화면 스트로브를 점멸시켜 가해자를 퇴치하고 주변 이목을 집중시킵니다.\n          </p>\n        </div>\n        <div class="card" style="border-color:rgba(245,158,11,0.4);">\n          <div style="font-size:26px; margin-bottom:10px;">📱</div>\n          <h3 style="color:#fde68a;">보호자 상황별 맞춤 연락</h3>\n          <p>\n            위기 정도에 따라 4단계 템플릿(귀가지연 안내 / 코스 이탈 주의 / 신변 위협 경계 / 긴급 조난 SOS)을 원터치 선택하여 <strong>실시간 지도 링크와 배터리 잔량</strong>을 즉시 보호자에게 전송합니다.\n          </p>\n        </div>\n        <div class="card" style="border-color:rgba(56,189,248,0.4);">\n          <div style="font-size:26px; margin-bottom:10px;">👥</div>\n          <h3 style="color:#7dd3fc;">피어(동서비스 이용자) SOS</h3>\n          <p>\n            경찰이 오기 전 골든타임을 확보하기 위해, 반경 1km 이내 <strong>동일 가디언 앱 사용자 및 등록된 로컬 지킴이(상인, 주민)</strong>들에게 긴급 위치와 도움 요청 푸시를 즉각 전파합니다.\n          </p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 10번 슬라이드: 119 원클릭 전송 목업 -->\n    <section class="slide">\n      <span class="badge red">RESCUE PACKAGE MOCKUP</span>\n      <h2>소방관이 오차 없이 출동하는 119 통합 리포트</h2>\n      <p class="desc">주소가 없는 한라산 둘레길이나 곶자왈에서도 즉각적인 수색이 가능한 표준 구조 데이터 패키지입니다.</p>\n      <div class="grid-2" style="align-items: center;">\n        <div>\n          <div class="card" style="margin-bottom: 12px;">\n            <h3 style="color:#34d399;">산악 국가지점번호 자동 매핑</h3>\n            <p>도로명 주소가 없는 야생 숲속에서도 119 상황실 지리정보시스템(GIS)에 직결되는 고유 좌표번호를 0.1초 만에 산출</p>\n          </div>\n          <div class="card" style="margin-bottom: 12px;">\n            <h3 style="color:#34d399;">외국인 관광객 다국어 TTS 음성 번역</h3>\n            <p>외국인 여행자가 터치 시 한국어로 자동 변환된 조난 음성 리포트가 119 상황실 요원에게 즉각 송출</p>\n          </div>\n          <div class="card">\n            <h3 style="color:#38bdf8;">주변 안심포인트 & 응급실 자동 병합</h3>\n            <p>구조대 출동 시 최기 거리의 거점 및 진입로 정보를 소방 상황실 단말기로 자동 전송</p>\n          </div>\n        </div>\n\n        <div class="mockup">\n          <div style="display:flex; justify-content:space-between; margin-bottom:14px; font-size:12px;">\n            <span style="color:#f43f5e; font-weight:700;">🚨 119 소방종합상황실 직결 데이터</span>\n            <span style="color:#64748b; font-family:monospace;">18:42:15 KST</span>\n          </div>\n          <div class="mockup-row"><span style="color:#94a3b8;">신고자/성별</span><span style="font-weight:600;">나홀로 여행자 (20대 여성)</span></div>\n          <div class="mockup-row"><span style="color:#94a3b8;">위경도 / 고도</span><span style="color:#34d399; font-family:monospace;">33.3617° N, 126.5292° E (420m)</span></div>\n          <div class="mockup-row"><span style="color:#94a3b8;">국가지점번호</span><span style="font-weight:700; color:#38bdf8; font-family:monospace;">다라 6245 8812</span></div>\n          <div class="mockup-row"><span style="color:#94a3b8;">배터리 / 통신</span><span style="color:#f59e0b; font-weight:600;">잔여 18% (라스트 핑 기록됨)</span></div>\n          <div class="mockup-row"><span style="color:#94a3b8;">주변 안심포인트</span><span style="color:#cbd5e1;">산천단 버스정류장 지킴이집 (380m)</span></div>\n          <div class="mockup-row"><span style="color:#94a3b8;">상황 분류</span><span style="color:#f43f5e; font-weight:700;">산간지역 14분 정체 (2단계 무응답)</span></div>\n          <button class="btn-emergency" onclick="alert(\'제주소방본부(119)에 구조 데이터 패키지가 원클릭 전송되었습니다.\')">\n            📞 제주소방본부(119) 원클릭 전송 및 직통 통화\n          </button>\n        </div>\n      </div>\n    </section>\n\n    <!-- 11번 슬라이드: 인터랙티브 가디언 콘솔 (Live Simulator) -->\n    <section class="slide">\n      <span class="badge" style="background:rgba(16,185,129,0.2); color:#34d399;">⚡ LIVE INTERACTIVE CONSOLE</span>\n      <h2>스마트 가디언 실시간 시뮬레이션 콘솔</h2>\n      <p class="desc" style="margin-bottom:12px;">발표 및 시연 시 실제 동작과 음향, 지오펜스를 브라우저에서 직접 조작해 볼 수 있는 인터랙티브 패널입니다.</p>\n\n      <div class="sim-panel">\n        <!-- 1열: 비상 경보 & 스텔스 / AI 동행 -->\n        <div style="display:flex; flex-direction:column; gap:10px;">\n          <div class="sim-box" style="border-color:rgba(244,63,94,0.3);">\n            <div class="sim-box-title">\n              <span style="color:#fb7185;">📢 최대 볼륨 사이렌</span>\n              <span style="font-size:10.5px; color:#94a3b8;">Web Audio API</span>\n            </div>\n            <button id="sirenBtn" class="siren-btn off" onclick="toggleSiren()">\n              <span id="sirenIcon" style="font-size:18px;">🚨</span>\n              <span id="sirenText">비상 사이렌 최대 볼륨 작동</span>\n            </button>\n          </div>\n\n          <div class="sim-box">\n            <div class="sim-box-title">\n              <span style="color:#fb7185;">🕵️ 스텔스 & AI 가상동행</span>\n            </div>\n            <button class="sim-btn danger" onclick="triggerStealthSos()">\n              <span>🕵️ 주머니 속 스텔스 무음 SOS</span>\n              <span style="color:#fb7185; font-size:10px;">30초 녹음</span>\n            </button>\n            <button class="sim-btn" onclick="openFakeCallModal()">\n              <span>📞 AI 가짜 통화 동행 시작</span>\n              <span style="color:#38bdf8; font-size:10px;">치한 퇴치</span>\n            </button>\n            <button class="sim-btn" onclick="toggleAnimalFrequency()">\n              <span id="freqBtnText">🐗 야생동물 기피 고주파 (20kHz)</span>\n              <span style="color:#fbbf24; font-size:10px;">음향방출</span>\n            </button>\n          </div>\n        </div>\n\n        <!-- 2열: 지오펜스 레이더 & 모빌리티 감지 -->\n        <div style="display:flex; flex-direction:column; gap:10px;">\n          <div class="sim-box">\n            <div class="sim-box-title">\n              <span style="color:#fbbf24;">⚠️ 위험 지오펜스 감지</span>\n            </div>\n            <button class="sim-btn danger" onclick="triggerCrimeAlert()">\n              <span>🚨 범죄주의구역 진입 감지</span>\n              <span style="color:#fb7185; font-size:10px;">우회로 권고</span>\n            </button>\n            <button class="sim-btn danger" onclick="triggerSexOffenderAlert()">\n              <span>🛡️ 성범죄자 주거지 반경 접근</span>\n              <span style="color:#fbbf24; font-size:10px;">여가부 알림e</span>\n            </button>\n            <button class="sim-btn" onclick="triggerSunsetTideAlert()">\n              <span>🌅 일몰 30분 전 & 만조 경보</span>\n              <span style="color:#34d399; font-size:10px;">기상/해양</span>\n            </button>\n          </div>\n\n          <div class="sim-box">\n            <div class="sim-box-title">\n              <span style="color:#c084fc;">🚗 모빌리티 & BLE 메시</span>\n            </div>\n            <button class="sim-btn" onclick="triggerTaxiOffRoute()">\n              <span>🚕 택시 경로 20% 이탈 감지</span>\n              <span style="color:#f87171; font-size:10px;">비정상 주행</span>\n            </button>\n            <button class="sim-btn" onclick="triggerBleMeshRelay()">\n              <span>📶 오프라인 BLE 메시 릴레이</span>\n              <span style="color:#38bdf8; font-size:10px;">음영극복</span>\n            </button>\n          </div>\n        </div>\n\n        <!-- 3열: 안심포인트 탐색 & 피어/보호자 SOS & 로그 -->\n        <div style="display:flex; flex-direction:column; gap:10px;">\n          <div class="sim-box">\n            <div class="sim-box-title">\n              <span style="color:#38bdf8;">📍 안심포인트 최단경로</span>\n            </div>\n            <div class="quick-list">\n              <div class="quick-item">\n                <div><strong>🏫 아동지킴이집</strong> (140m)</div>\n                <span class="route-badge" onclick="guideRoute(\'삼도2동 아동지킴이집\', 140, 2)">안내</span>\n              </div>\n              <div class="quick-item">\n                <div><strong>🏪 GS25 안심편의점</strong> (210m)</div>\n                <span class="route-badge" onclick="guideRoute(\'GS25 제주탑동안심점\', 210, 3)">안내</span>\n              </div>\n              <div class="quick-item">\n                <div><strong>🏥 한국병원 응급실</strong> (1.2km)</div>\n                <span class="route-badge" style="background:rgba(244,63,94,0.2); color:#fb7185;" onclick="guideRoute(\'한국병원 응급실\', 1200, 4, true)">응급실</span>\n              </div>\n            </div>\n          </div>\n\n          <div class="sim-box">\n            <div class="sim-box-title">\n              <span style="color:#fde68a;">👥 피어 & 보호자 연락</span>\n            </div>\n            <div style="display:flex; gap:6px;">\n              <button class="sim-btn" style="flex:1; background:#1e1b4b; border-color:#4338ca;" onclick="triggerPeerSos()">\n                <span>👥 피어 SOS</span>\n              </button>\n              <button class="sim-btn" style="flex:1; background:#312e81; border-color:#4f46e5;" onclick="openGuardianModal()">\n                <span>📱 보호자 템플릿</span>\n              </button>\n            </div>\n            <div id="simLog" class="sim-log">\n              [시스템] 세이프 가디언 엔진 정상 가동 중<br>\n              [GPS] 제주시 삼도이동 (안심 궤적 추적 중)\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- 12번 슬라이드: 비전 및 로드맵 -->\n    <section class="slide center" style="text-align: center; max-width: 880px;">\n      <span class="badge">FUTURE ROADMAP</span>\n      <h2>혼자 와도 두려움 없는 안심 대한민국</h2>\n      <p class="desc">\n        제주특별자치도, 행정안전부, 경찰청, 소방청, 여성가족부 공공데이터를 유기적으로 연계하여<br>\n        <strong>\'사후 수색\' 중심에서 \'사전 차단 & 실시간 초동 구난\'</strong>으로 안전 패러다임을 대전환합니다.\n      </p>\n      <div class="grid-3" style="text-align: left; margin-top: 10px;">\n        <div class="card">\n          <span class="card-tag">Phase 1 (MVP)</span>\n          <h3>제주 특화 안전 실증</h3>\n          <p>날씨·일몰·만조, 올레길 2단계 체크인, 스텔스 SOS, 사이렌 및 119 구조 리포트 구축 완료</p>\n        </div>\n        <div class="card">\n          <span class="card-tag">Phase 2 (확장)</span>\n          <h3>전국 안심망 & 모빌리티</h3>\n          <p>경찰청 범죄지도, 성범죄자 알림, 택시·렌터카 e-Call, 안심포인트 24시 거점 전국 인프라 통합</p>\n        </div>\n        <div class="card">\n          <span class="card-tag">Phase 3 (글로벌)</span>\n          <h3>외국인 K-Safety 솔루션</h3>\n          <p>다국어 119 음성 통역, 공항 안심 스마트 밴드 대여 및 글로벌 관광객 필수 안심 플랫폼 도약</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 13번 슬라이드: 네이티브 앱 & 통합 관제 아키텍처 [NEW] -->\n    <section class="slide">\n      <span class="badge cyan">TECHNICAL ARCHITECTURE</span>\n      <h2>아이폰/안드로이드 네이티브 앱 & 웹 통합 관제 아키텍처</h2>\n      <p class="desc">백그라운드 센서 제어의 정밀성을 위해 네이티브 모바일 코어와 대용량 실시간 관제 백엔드를 설계합니다.</p>\n      <div class="grid-3">\n        <div class="card">\n          <div class="card-tag" style="background:rgba(56,189,248,0.15); color:#38bdf8;">모바일 클라이언트</div>\n          <h3>iOS & Android 네이티브</h3>\n          <p>\n            <strong>iOS:</strong> Swift 6, CoreLocation(초절전 백그라운드), CoreBluetooth(BLE 메시), CallKit/AVAudioSession(사이렌), Live Activity.<br>\n            <strong>Android:</strong> Kotlin, Foreground Service, GeofencingClient, Nearby Connections, Accessibility/DND Bypass.\n          </p>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="background:rgba(16,185,129,0.15); color:#34d399;">클라우드 백엔드</div>\n          <h3>실시간 이벤트 파이프라인</h3>\n          <p>\n            <strong>엔진:</strong> FastAPI/Go 마이크로서비스, Redis Geo(반경 검색/지오펜싱), PostGIS(안심경로/공공데이터 공간연산).<br>\n            <strong>스트리밍:</strong> Kafka/RabbitMQ(119 E-Call 직결), WebRTC/WebSocket(실시간 위치 중계 및 피어 전파).\n          </p>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="background:rgba(168,85,247,0.15); color:#c084fc;">통합 관제 시스템</div>\n          <h3>웹 관리자 대시보드 (Next.js)</h3>\n          <p>\n            <strong>GIS 상황판:</strong> Mapbox GL / Kakao Maps 연동, 실시간 위기 탐방객 핀포인트 모니터링.<br>\n            <strong>위기 대응:</strong> 10분 이상 정체자, 코스 이탈자, 피어 SOS 발생 현황 자동 경보 및 119/112 출동 이력 관리.\n          </p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 14번 슬라이드: OS별 제약 및 불가능한 항목 검토 [NEW] -->\n    <section class="slide">\n      <span class="badge red">OS POLICY & LIMITATION ANALYSIS</span>\n      <h2>iOS / Android OS별 기술적 제약 및 우회 해결책 검토</h2>\n      <p class="desc">모바일 OS의 샌드박스 및 보안 정책상 직면하는 불가능한 요소와 이를 돌파하기 위한 우회 설계를 명시합니다.</p>\n      <table class="spec-table">\n        <thead>\n          <tr>\n            <th style="width: 20%;">기능 항목</th>\n            <th style="width: 22%;">Android 환경</th>\n            <th style="width: 25%;">iOS (iPhone) 환경</th>\n            <th style="width: 33%;">기술적 한계 & 실무 우회 방안</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>스텔스 SOS (전원 5회 클릭)</strong></td>\n            <td><span class="tag-diff-low">가능</span> (AccessibilityService 또는 MediaButton 트리거)</td>\n            <td><span class="tag-diff-high">불가</span> (화면 꺼짐 시 하드웨어 전원키 이벤트 접근 차단)</td>\n            <td><strong>우회:</strong> iOS는 \'뒷면 탭하기(Back Tap)\', 잠금화면 위젯, 볼륨키 롱프레스, 애플워치 액션버튼 연동으로 대체</td>\n          </tr>\n          <tr>\n            <td><strong>무음모드 강제돌파 최대사이렌</strong></td>\n            <td><span class="tag-diff-low">가능</span> (NotificationManager 방해금지 해제 권한)</td>\n            <td><span class="tag-diff-high">제한적</span> (물리 무음 스위치 켜짐 시 AVAudioSession 우회 제한)</td>\n            <td><strong>우회:</strong> Apple에 <strong>\'Critical Alerts(긴급재난경보)\'</strong> Entitlement 정식 신청/승인 또는 오디오 세션 카테고리 `.playback` 설정</td>\n          </tr>\n          <tr>\n            <td><strong>숙소 Wi-Fi 몰카 IP 스캔</strong></td>\n            <td><span class="tag-diff-med">제한적</span> (Android 11+ MAC 주소 마스킹)</td>\n            <td><span class="tag-diff-high">제한적</span> (로컬 네트워크 접근 권한 & ARP 테이블 차단)</td>\n            <td><strong>우회:</strong> mDNS/Bonjour 프로토콜 기반 RTSP/ONVIF 카메라 포트(554, 8080) 열림 여부만 스캐닝하는 네트워크 분석 방식으로 전환</td>\n          </tr>\n          <tr>\n            <td><strong>성범죄자 알림e 지도 표기</strong></td>\n            <td><span class="tag-diff-low">앱 구현 가능</span></td>\n            <td><span class="tag-diff-low">앱 구현 가능</span></td>\n            <td><strong>법적 한계:</strong> 아청법상 성범죄자 신상정보 재배포·스크래핑은 5년 이하 징역. ➔ <strong>해결:</strong> 개별 주소가 아닌 \'지자체 치안 취약 등급 지오펜스\'로 가공 표출</td>\n          </tr>\n        </tbody>\n      </table>\n    </section>\n\n    <!-- 15번 슬라이드: 백엔드 & 통합 관제 관리자 기능 명세 [NEW] -->\n    <section class="slide">\n      <span class="badge amber">ADMIN & DISPATCH CONSOLE</span>\n      <h2>통합 관제탑(Admin) 핵심 관리자 기능 명세</h2>\n      <p class="desc">지자체(제주도청), 소방 종합상황실, 경찰서에서 24시간 실시간으로 감시 및 초동 조치하는 관제 시스템입니다.</p>\n      <div class="grid-2">\n        <div class="card">\n          <div class="card-tag" style="background:rgba(245,158,11,0.15); color:#fbbf24;">실시간 GIS 관제 기능</div>\n          <h3>1. 제주 & 전국 실시간 여행자 상황판</h3>\n          <p style="margin-bottom:10px;">수만 명의 동시 접속 여행자 중 \'위험 징후\'가 감지된 사용자만 필터링하여 관제합니다.</p>\n          <ul style="list-style:none; font-size:12px; color:#cbd5e1; display:flex; flex-direction:column; gap:6px;">\n            <li>📍 <strong>실시간 클러스터링 지도:</strong> 전체 활동자 핀포인트 및 위험도(정상/주의/위험/조난) 색상 표출</li>\n            <li>⏱️ <strong>이상 정체/이탈 알람:</strong> 10분 이상 이동 0 정체자, 올레 코스 200m 이탈자 즉각 팝업 경보</li>\n            <li>📡 <strong>통신 두절자 라스트 핑 추적:</strong> 신호 끊긴 탐방객의 최종 정상 좌표 및 이동 방향 예상 경로 산출</li>\n            <li>👥 <strong>피어 SOS 활성화 맵:</strong> 도움 요청이 발생한 반경 1km 내 가용 인력(동행자/상인) 현황 실시간 중계</li>\n          </ul>\n        </div>\n        <div class="card">\n          <div class="card-tag" style="background:rgba(56,189,248,0.15); color:#38bdf8;">구조 출동 & 자원 관리</div>\n          <h3>2. 119/112 원클릭 출동 지령 & 데이터 관리</h3>\n          <p style="margin-bottom:10px;">소방·경찰 상황실과의 원스톱 연동 및 현장 안전 인프라를 등록·유지보수합니다.</p>\n          <ul style="list-style:none; font-size:12px; color:#cbd5e1; display:flex; flex-direction:column; gap:6px;">\n            <li>🚨 <strong>소방 직결 지령 카드:</strong> 조난자의 국가지점번호, 고도, 배터리 잔량, 의료정보를 출동 지령서로 즉시 발권</li>\n            <li>🏪 <strong>안심포인트 인프라 CRUD:</strong> 아동지킴이, 24시 편의점, AED, 주유소 위치 및 야간 운영상태 실시간 갱신</li>\n            <li>📊 <strong>위험구역 빅데이터 분석:</strong> 조난 빈발 지점, 신고 다발 골목길 히트맵 분석을 통해 지자체 CCTV/가로등 증설 제안</li>\n            <li>🔐 <strong>개인정보 암호화 열람:</strong> 위기 발생 시에만 보호자/경찰에게 제한적으로 열람 권한을 부여하는 감사 로그 시스템</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <!-- 16번 슬라이드: 모바일 앱 핵심 모듈별 개발 구현 기법 [NEW] -->\n    <section class="slide">\n      <span class="badge indigo">CORE MODULE IMPLEMENTATION</span>\n      <h2>모바일 앱 핵심 모듈별 개발 구현 기법</h2>\n      <p class="desc">배터리 소모를 최소화하면서 위기 순간 센서를 100% 가동시키는 기술 명세입니다.</p>\n      <div class="grid-3">\n        <div class="card">\n          <div style="font-size:24px; margin-bottom:8px;">🔋</div>\n          <h3 style="color:#34d399;">초절전 하이브리드 GPS</h3>\n          <p>\n            평상시에는 기지국/Wi-Fi 기반 <strong>대략적 위치(Cell-ID)</strong>로 배터리를 1% 미만으로 절약하고, 산악·올레길 진입 지오펜스 통과 시에만 <strong>고정밀 칼만 필터 GPS</strong>로 자동 승격 전환합니다.\n          </p>\n        </div>\n        <div class="card">\n          <div style="font-size:24px; margin-bottom:8px;">📶</div>\n          <h3 style="color:#38bdf8;">BLE 오프라인 메시 네트워크</h3>\n          <p>\n            Android의 <strong>Nearby Connections API</strong>와 iOS의 <strong>CoreBluetooth Peripheral/Central 동시 모드</strong>를 활용하여 통신 음영 지대에서 초당 1회 조난 패킷을 주변 스마트폰으로 홉(Hop) 전파합니다.\n          </p>\n        </div>\n        <div class="card">\n          <div style="font-size:24px; margin-bottom:8px;">🎙️</div>\n          <h3 style="color:#fb7185;">백그라운드 스텔스 녹음기</h3>\n          <p>\n            스텔스 SOS 트리거 시 화면 렌더링을 완전히 차단한 상태에서 <strong>AVAudioRecorder / MediaRecorder</strong>를 무음 가동, AAC/M4A 64kbps로 30초 압축 후 백그라운드 멀티파트 업로드합니다.\n          </p>\n        </div>\n      </div>\n    </section>\n\n    <!-- 17번 슬라이드: 개발 난이도, 개발 기간 및 공수(MM) 산정표 [NEW] -->\n    <section class="slide">\n      <span class="badge amber">WBS & MAN-MONTH ESTIMATION</span>\n      <h2>개발 난이도, 개발 기간 및 소요 공수(MM) 산정</h2>\n      <p class="desc">기능별 기술 난이도와 모바일 앱 2종(iOS/Android) + 백엔드 + 웹 관제 시스템 구축에 필요한 투입 공수입니다.</p>\n      <table class="spec-table" style="margin-bottom:12px;">\n        <thead>\n          <tr>\n            <th>구분 / 서브시스템</th>\n            <th>핵심 개발 항목</th>\n            <th>기술 난이도</th>\n            <th>개발 기간</th>\n            <th>투입 공수 (MM)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>iOS 네이티브 앱</strong></td>\n            <td>CoreLocation 초절전 궤적, BLE 메시, Critical Alerts, 스텔스 SOS, 라이브 액티비티</td>\n            <td><span class="tag-diff-high">상 (High)</span></td>\n            <td>4.5개월</td>\n            <td><strong>6.0 MM</strong> (선임 1명, 중급 1명)</td>\n          </tr>\n          <tr>\n            <td><strong>Android 네이티브 앱</strong></td>\n            <td>포그라운드 서비스, DND 해제 사이렌, Accessibility 물리키 캡처, Nearby 메시</td>\n            <td><span class="tag-diff-high">상 (High)</span></td>\n            <td>4.5개월</td>\n            <td><strong>6.0 MM</strong> (선임 1명, 중급 1명)</td>\n          </tr>\n          <tr>\n            <td><strong>클라우드 백엔드</strong></td>\n            <td>FastAPI/PostGIS 공간연산, Redis 지오펜스, 공공데이터 연동, 119 E-Call 파이프라인</td>\n            <td><span class="tag-diff-med">중상 (Med-High)</span></td>\n            <td>4.0개월</td>\n            <td><strong>6.0 MM</strong> (백엔드 1명, 인프라/DBA 1명)</td>\n          </tr>\n          <tr>\n            <td><strong>웹 통합 관제 시스템</strong></td>\n            <td>Next.js 기반 대용량 GIS 상황판, 실시간 WebSocket 모니터링, 출동 지령 CRUD</td>\n            <td><span class="tag-diff-med">중 (Medium)</span></td>\n            <td>3.5개월</td>\n            <td><strong>4.0 MM</strong> (프론트엔드 개발자 1명)</td>\n          </tr>\n          <tr>\n            <td><strong>기획 / UIUX / QA</strong></td>\n            <td>화면설계, 디자인 시스템, 현장 필드테스트(한라산/곶자왈), 보안성 검토</td>\n            <td><span class="tag-diff-low">중 (Medium)</span></td>\n            <td>전 기간</td>\n            <td><strong>10.0 MM</strong> (PM 4, 디자이너 3, QA 3)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div style="background:#0f172a; border:1px solid #1e293b; padding:10px 16px; border-radius:8px; display:flex; justify-content:space-between; align-items:center; font-size:12.5px;">\n        <span style="color:#cbd5e1;">📌 <strong>총 개발 기간:</strong> 6개월 (MVP 3.5개월 + 관제 연동 1.5개월 + 실증 1개월)</span>\n        <span style="color:#34d399; font-weight:800; font-size:14px;">총 소요 공수: 32.0 Man-Months (MM)</span>\n      </div>\n    </section>\n\n    <!-- 18번 슬라이드: 단계별 론칭 로드맵 & 기대효과 [NEW] -->\n    <section class="slide center" style="text-align: center; max-width: 880px;">\n      <span class="badge">DEVELOPMENT ROADMAP</span>\n      <h2>단계별 구축 계획 및 상용화 성공 전략</h2>\n      <p class="desc">\n        체계적인 3단계 개발 마일스톤을 통해 <strong>안정성을 검증하고 공공·민간 통합 안전망</strong>을 완성합니다.\n      </p>\n      <div class="grid-3" style="text-align: left; margin-top: 10px;">\n        <div class="card">\n          <span class="card-tag">Sprint 1 (1~2개월)</span>\n          <h3>코어 센서 & 모바일 엔진</h3>\n          <p>\n            - iOS / Android 초절전 궤적 추적 모듈<br>\n            - 2단계 데드맨 스위치 & 사이렌 합성기<br>\n            - 공공데이터(기상청/천문연) 수집 파이프라인\n          </p>\n        </div>\n        <div class="card">\n          <span class="card-tag">Sprint 2 (3~4개월)</span>\n          <h3>관제탑 & 통신음영 극복</h3>\n          <p>\n            - Next.js 기반 실시간 GIS 관제 대시보드<br>\n            - BLE 메시 P2P 릴레이 & 스텔스 SOS<br>\n            - 안심포인트 최단경로 & 보호자 SMS 연동\n          </p>\n        </div>\n        <div class="card">\n          <span class="card-tag">Sprint 3 (5~6개월)</span>\n          <h3>소방 실증 & 상용 배포</h3>\n          <p>\n            - 제주 산간·올레길 현장 통신음영 필드테스트<br>\n            - 애플 Critical Alerts 심사 & 스토어 런칭<br>\n            - 제주소방본부 119 직결 시범 운영\n          </p>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- 보호자 상황별 연락 모달 -->\n  <div id="guardianModal" class="sim-modal" onclick="closeModalOnBackdrop(event, \'guardianModal\')">\n    <div class="sim-modal-content">\n      <div style="display:flex; justify-content:space-between; align-items:center;">\n        <h3 style="font-size:15px; color:#fff;">📱 보호자 상황별 긴급 연락</h3>\n        <button onclick="closeModal(\'guardianModal\')" style="background:none; border:none; color:#94a3b8; font-size:18px; cursor:pointer;">✕</button>\n      </div>\n      <p style="font-size:12px; color:#94a3b8;">상황을 선택하면 현재 실시간 GPS 위치와 맞춤형 문구가 보호자에게 원클릭 전송됩니다.</p>\n      <div style="display:flex; flex-direction:column; gap:8px;">\n        <button class="sim-btn" onclick="sendGuardianAlert(\'단순 귀가지연\', \'현재 안전하게 이동 중이며 예상보다 30분 늦어지고 있습니다.\')">\n          <span>🕒 1. 단순 귀가지연 (안심 확인)</span>\n        </button>\n        <button class="sim-btn" onclick="sendGuardianAlert(\'코스 이탈\', \'등산로/올레길 코스를 일시 이탈하여 정상 경로 복귀 중입니다.\')">\n          <span>🧭 2. 정규 코스 이탈 주의</span>\n        </button>\n        <button class="sim-btn danger" onclick="sendGuardianAlert(\'신변 위협 의심\', \'수상한 인물이 뒤따라와 인근 안심편의점으로 피신 중입니다.\')">\n          <span>⚠️ 3. 신변 위협 / 스토킹 의심 피신</span>\n        </button>\n        <button class="sim-btn danger" onclick="sendGuardianAlert(\'긴급 조난/부상\', \'낙상 부상으로 이동이 불가능하여 긴급 구조가 필요합니다!\')">\n          <span>🚨 4. 긴급 조난 / 부상 (119 병합)</span>\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- AI 가짜 통화 모달 -->\n  <div id="fakeCallModal" class="sim-modal" onclick="closeModalOnBackdrop(event, \'fakeCallModal\')">\n    <div class="sim-modal-content" style="background:#0b1320; border-color:#38bdf8; text-align:center;">\n      <div style="font-size:42px; margin-top:8px;">📱</div>\n      <h3 style="color:#38bdf8; font-size:17px; margin-top:4px;">AI 가상 동행 통화 중...</h3>\n      <div style="font-size:13px; color:#94a3b8; margin-bottom:10px;">수신자: 엄마 (가상 음성 가이드)</div>\n      \n      <div style="background:#1e293b; border-radius:10px; padding:12px; text-align:left; font-size:12.5px; color:#e2e8f0; line-height:1.6;">\n        <span style="color:#34d399; font-weight:700;">AI:</span> "응, 거의 다 왔어? 지금 편의점 앞 골목이지? 내가 대문 열어놓을 테니까 천천히 들어와~"\n      </div>\n      <p style="font-size:11.5px; color:#64748b;">(가해자에게 통화 중임을 인식시키며 실시간 위치가 보호자에게 자동 중계되고 있습니다)</p>\n\n      <button class="btn-emergency" style="background:#334155; margin-top:10px;" onclick="closeModal(\'fakeCallModal\')">\n        통화 종료 (안심 복귀)\n      </button>\n    </div>\n  </div>\n\n  <!-- 하단 컨트롤 버튼 -->\n  <footer>\n    <div class="key-tip">단축키: 키보드 [←] [→] 또는 [Space] | 총 18개 슬라이드 완비</div>\n    <div class="btn-group">\n      <button id="prevBtn" class="nav-btn btn-prev" onclick="prev()">이전</button>\n      <button id="nextBtn" class="nav-btn btn-next" onclick="next()">다음</button>\n      <button id="fullBtn" class="nav-btn btn-full" onclick="toggleFullScreen()">⛶ 전체화면</button>\n    </div>\n  </footer>\n\n  <!-- 슬라이드 제어 및 인터랙티브 자바스크립트 -->\n  <script>\n    let slides = [];\n    let prevBtn = null;\n    let nextBtn = null;\n    let fullBtn = null;\n    let counter = null;\n    let progBar = null;\n\n    let current = 0;\n    let total = 0;\n\n    function render(idx) {\n      if (!slides || slides.length === 0) return;\n      current = idx;\n      slides.forEach((s, i) => s.classList.toggle(\'active\', i === idx));\n      if (counter) {\n        counter.textContent = `${String(idx + 1).padStart(2, \'0\')} / ${String(total).padStart(2, \'0\')}`;\n      }\n      if (progBar) {\n        progBar.style.width = `${((idx + 1) / total) * 100}%`;\n      }\n      if (prevBtn) {\n        prevBtn.disabled = (idx === 0);\n      }\n      if (nextBtn) {\n        nextBtn.textContent = (idx === total - 1) ? \'처음으로\' : \'다음\';\n      }\n      window.scrollTo({ top: 0, behavior: \'smooth\' });\n    }\n\n    function next() {\n      if (total === 0) return;\n      current = (current + 1) % total;\n      render(current);\n    }\n\n    function prev() {\n      if (total === 0) return;\n      if (current > 0) {\n        current--;\n        render(current);\n      }\n    }\n\n    function toggleFullScreen() {\n      if (!document.fullscreenElement) {\n        document.documentElement.requestFullscreen().catch(() => {});\n      } else {\n        document.exitFullscreen().catch(() => {});\n      }\n    }\n\n    window.addEventListener(\'DOMContentLoaded\', () => {\n      initSlides();\n    });\n\n    function initSlides() {\n      slides = document.querySelectorAll(\'.slide\');\n      prevBtn = document.getElementById(\'prevBtn\');\n      nextBtn = document.getElementById(\'nextBtn\');\n      fullBtn = document.getElementById(\'fullBtn\');\n      counter = document.getElementById(\'slideCounter\');\n      progBar = document.getElementById(\'progressBar\');\n      total = slides.length;\n      render(0);\n    }\n\n    window.addEventListener(\'keydown\', (e) => {\n      if (e.target.tagName === \'INPUT\' || e.target.tagName === \'TEXTAREA\') return;\n      if (e.key === \'ArrowRight\' || e.key === \'Space\') {\n        e.preventDefault();\n        next();\n      } else if (e.key === \'ArrowLeft\') {\n        e.preventDefault();\n        prev();\n      }\n    });\n\n    // 즉시 실행\n    initSlides();\n\n    /* ========================================================\n       인터랙티브 가디언 콘솔 (Web Audio API 사이렌 및 시뮬레이터)\n       ======================================================== */\n    let audioCtx = null;\n    let sirenOsc = null;\n    let sirenGain = null;\n    let sirenLfo = null;\n    let isSirenPlaying = false;\n\n    let animalOsc = null;\n    let isAnimalPlaying = false;\n\n    function logEvent(msg) {\n      const log = document.getElementById(\'simLog\');\n      if (!log) return;\n      const time = new Date().toLocaleTimeString(\'ko-KR\', { hour12: false });\n      log.innerHTML = `[${time}] ${msg}<br>` + log.innerHTML;\n    }\n\n    function toggleSiren() {\n      if (isSirenPlaying) {\n        stopSiren();\n      } else {\n        startSiren();\n      }\n    }\n\n    function startSiren() {\n      try {\n        const AudioContext = window.AudioContext || window.webkitAudioContext;\n        audioCtx = new AudioContext();\n\n        sirenOsc = audioCtx.createOscillator();\n        sirenGain = audioCtx.createGain();\n        sirenLfo = audioCtx.createOscillator();\n        const lfoGain = audioCtx.createGain();\n\n        sirenOsc.type = \'sawtooth\';\n        sirenOsc.frequency.setValueAtTime(750, audioCtx.currentTime);\n\n        sirenLfo.type = \'sine\';\n        sirenLfo.frequency.setValueAtTime(1.2, audioCtx.currentTime);\n        lfoGain.gain.setValueAtTime(350, audioCtx.currentTime);\n\n        sirenLfo.connect(lfoGain);\n        lfoGain.connect(sirenOsc.frequency);\n\n        sirenGain.gain.setValueAtTime(0.4, audioCtx.currentTime);\n\n        sirenOsc.connect(sirenGain);\n        sirenGain.connect(audioCtx.destination);\n\n        sirenOsc.start();\n        sirenLfo.start();\n        isSirenPlaying = true;\n\n        document.getElementById(\'sirenBtn\').className = \'siren-btn on\';\n        document.getElementById(\'sirenIcon\').textContent = \'⏹️\';\n        document.getElementById(\'sirenText\').textContent = \'비상 사이렌 중지 (120dB 경보 중)\';\n        document.getElementById(\'screenStrobe\').style.display = \'block\';\n\n        logEvent(\'🚨 [긴급경보] 최대 볼륨 비상 사이렌 및 스트로브 플래시 작동\');\n      } catch (e) {\n        alert(\'브라우저 오디오 권한이 필요합니다: \' + e.message);\n      }\n    }\n\n    function stopSiren() {\n      if (sirenOsc) {\n        try {\n          sirenOsc.stop();\n          sirenLfo.stop();\n          audioCtx.close();\n        } catch (e) {}\n      }\n      isSirenPlaying = false;\n      document.getElementById(\'sirenBtn\').className = \'siren-btn off\';\n      document.getElementById(\'sirenIcon\').textContent = \'🚨\';\n      document.getElementById(\'sirenText\').textContent = \'비상 사이렌 최대 볼륨 작동\';\n      document.getElementById(\'screenStrobe\').style.display = \'none\';\n\n      logEvent(\'⏹️ [경보해제] 비상 사이렌 정상 중지\');\n    }\n\n    function toggleAnimalFrequency() {\n      if (isAnimalPlaying) {\n        if (animalOsc) {\n          try { animalOsc.stop(); } catch(e){}\n        }\n        isAnimalPlaying = false;\n        document.getElementById(\'freqBtnText\').textContent = \'🐗 야생동물 기피 고주파 (20kHz)\';\n        logEvent(\'⏹️ [기피음 해제] 고주파 방출 중지\');\n      } else {\n        try {\n          const AudioContext = window.AudioContext || window.webkitAudioContext;\n          const actx = new AudioContext();\n          animalOsc = actx.createOscillator();\n          const gain = actx.createGain();\n          animalOsc.type = \'sine\';\n          animalOsc.frequency.setValueAtTime(19500, actx.currentTime);\n          gain.gain.setValueAtTime(0.2, actx.currentTime);\n          animalOsc.connect(gain);\n          gain.connect(actx.destination);\n          animalOsc.start();\n          isAnimalPlaying = true;\n          document.getElementById(\'freqBtnText\').textContent = \'⏹️ 기피 고주파 방출 중 (정지)\';\n          logEvent(\'🐗 [야생동물 기피] 들개·멧돼지 기피 고주파(19.5kHz) 방출 중\');\n        } catch(e) {\n          alert(\'오디오 권한 필요: \' + e.message);\n        }\n      }\n    }\n\n    function triggerStealthSos() {\n      logEvent(\'🕵️ [스텔스 SOS] 화면 꺼진 상태 전원버튼 5회 감지 ➔ 30초 현장 오디오 녹음 및 좌표 백그라운드 전송 완료!\');\n      alert(`🕵️ [주머니 속 스텔스 무음 SOS 작동]\\n\\n화면을 켜지 않은 상태에서 은밀히 작동되었습니다.\\n- 30초 현장 오디오 녹음 시작\\n- 실시간 좌표(33.5134° N, 126.5270° E) 112 및 보호자 자동 전송`);\n    }\n\n    function openFakeCallModal() {\n      document.getElementById(\'fakeCallModal\').style.display = \'flex\';\n      logEvent(\'📞 [가상 동행] AI 가짜 통화 화면 실행 ➔ 실시간 위치 보호자 중계 중\');\n    }\n\n    function triggerTaxiOffRoute() {\n      logEvent(\'🚕 [택시 경로이탈] 권장 경로 25% 이탈 감지! 인적 드문 외딴길 진입 ➔ 보호자 알림\');\n      alert(`🚕 [택시 비정상 경로 이탈 감지]\\n\\n설정된 목적지 권장 경로 대비 25% 이상 벗어났습니다.\\n현재 경로가 보호자에게 실시간 중계되며, 위기 시 즉시 사이렌을 작동하세요.`);\n    }\n\n    function triggerBleMeshRelay() {\n      logEvent(\'📶 [BLE 메시] LTE 기지국 두절 감지 ➔ 반경 45m 내 등산객 B씨 단말과 P2P 패킷 릴레이 연결 성공\');\n      alert(`📶 [오프라인 BLE 메시 릴레이 가동]\\n\\n통신 음영 구역에 진입했습니다.\\n주변 45m 지점의 다른 탐방객 스마트폰과 블루투스 P2P 연결이 완료되어 조난 신호 전달 대기 중입니다.`);\n    }\n\n    function triggerCrimeAlert() {\n      logEvent(\'⚠️ [치안경보] 범죄주의구역(야간 조도 취약지) 반경 50m 진입! 햅틱 진동 및 안전 우회로 권고\');\n      alert(`🚨 [위험알림] 범죄주의구역 진입 감지!\\n\\n현재 구역은 최근 야간 절도/폭행 다발 및 가로등 미설치 구간입니다.\\n주변 140m 지점의 [아동지킴이집] 또는 대로변으로 우회 이동하십시오.`);\n    }\n\n    function triggerSexOffenderAlert() {\n      logEvent(\'🛡️ [여가부 연계] 성범죄자 알림e 반경 200m 경계구역 통과 감지 (지능형 사전 주의 가이드 발송)\');\n      alert(`🛡️ [성범죄자 알림e 안내]\\n\\n반경 200m 내 신상공개 대상자 거주 구역을 통과 중입니다.\\n이어폰 착용을 자제하고 대로변 및 안심 귀갓길을 이용해 주십시오.`);\n    }\n\n    function triggerSunsetTideAlert() {\n      logEvent(\'🌅 [기상청/천문연] 오늘 일몰 시각(18:35) 30분 전! 산악 등반객 하산 권고 발송\');\n      logEvent(\'🌊 [국립해양조사원] 제주 용두암 해안 만조 40분 전! 갯바위 접근 금지 및 대피 경보\');\n      alert(`🌅 [기관데이터 실시간 알림]\\n\\n1. [천문연구원] 당일 일몰 30분 전 도달: 산간 조난 위험, 하산 권고.\\n2. [해양조사원] 해안 만조 시간 40분 전: 갯바위 밀물 침수 위험 대피 권고.`);\n    }\n\n    function guideRoute(name, dist, min, isHospital = false) {\n      logEvent(`📍 [최단경로 안내] [${name}]까지 최단 대피 경로 탐색 완료 (${dist}m, 도보 ${min}분 소요)`);\n      alert(`📍 [최단 대피로 안내]\\n\\n목적지: ${name}\\n거리: ${dist}m (예상 소요시간: ${min}분)\\n\\n가장 밝은 대로변을 경유하는 최단 안전 대피 경로 내비게이션을 활성화합니다.`);\n    }\n\n    function triggerPeerSos() {\n      logEvent(\'👥 [피어 SOS] 반경 1km 내 동일 가디언 앱 이용자 4명에게 긴급 원조 요청 푸시 전송 완료!\');\n      alert(`👥 [피어 SOS 전파 완료]\\n\\n반경 1km 내 가디언 이용자 4명 및 인근 안심편의점 점주에게 도움 요청 알림이 발송되었습니다.`);\n    }\n\n    function openGuardianModal() {\n      document.getElementById(\'guardianModal\').style.display = \'flex\';\n    }\n\n    function closeModal(id) {\n      document.getElementById(id).style.display = \'none\';\n    }\n\n    function closeModalOnBackdrop(e, id) {\n      if (e.target.id === id) {\n        closeModal(id);\n      }\n    }\n\n    function sendGuardianAlert(type, text) {\n      closeModal(\'guardianModal\');\n      logEvent(`📱 [보호자 전송] 상황: [${type}] - 좌표(33.5134° N, 126.5270° E) 및 배터리 정보 전송됨`);\n      alert(`📱 [보호자 긴급 문자 전송 완료]\\n\\n유형: ${type}\\n내용: "${text}"\\n첨부: 실시간 GPS 위치 지도 링크, 배터리 잔량 78%`);\n    }\n  </script>\n</body>\n</html>\n';

export default {
  async fetch(request, env, ctx) {
    return new Response(htmlContent, {
      headers: {
        'content-type': 'text/html;charset=UTF-8',
        'cache-control': 'public, max-age=3600'
      }
    });
  }
};
